WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN amount >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, COUNT(*) FILTER (WHERE txn_type = 'DEBIT') AS debit_rows, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, GROUPING(CASE WHEN amount >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM sessions_transactions GROUP BY CUBE (CASE WHEN amount >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING COUNT(*) FILTER (WHERE txn_type = 'DEBIT') < 1000
